--
-- Cấu trúc bảng cho bảng `blogs`
--

CREATE TABLE `blogs` (
  `id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `summary` text DEFAULT NULL,
  `content` text DEFAULT NULL,
  `image` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Đang đổ dữ liệu cho bảng `blogs`
--

INSERT INTO `blogs` (`id`, `title`, `summary`, `content`, `image`, `created_at`) VALUES
(1, 'Kỹ thuật quăng mồi Lure xa bờ cho người mới', 'Chia sẻ mẹo thắt nút dây PE và cách điều chỉnh lực phanh máy ngang để không bị rối rác.', 'Nội dung chi tiết bài viết hướng dẫn cần thủ căn góc quăng mồi hiệu quả...', 'data:image/jpeg;base64,', '2026-06-01 10:07:12'),
(2, 'Cách bảo dưỡng ổ bi (Bearing) máy câu Shimano', 'Hướng dẫn tra dầu chuyên dụng giúp máy câu hoạt động mượt mà sau khi câu biển.', 'Chi tiết quy trình tháo bánh răng và vệ sinh muối mặn bám trên máy câu...', 'data:image/jpeg;base64,', '2026-06-01 10:07:12'),
(3, 'Bí quyết chọn cần câu Lure máy đứng và máy ngang cho người mới', 'Hướng dẫn chi tiết cách phân biệt thông số độ cứng (L, ML, M, MH) và hành trình đọt cần khi câu cá lóc, cá chẽm.', '<p>Đối với bộ môn câu lure, việc chọn đúng chiếc cần phù hợp với địa hình và con mồi là yếu tố quyết định đến 70% thành công của chuyến đi.</p><h5>1. Chọn cần máy đứng (Spinning)</h5><p>Cần máy đứng thích hợp cho người mới bắt đầu vì tính dễ sử dụng, ít bị rối dây (backlash). Thích hợp quăng các loại mồi giả trọng lượng nhẹ...</p><h5>2. Chọn cần máy ngang (Baitcasting)</h5><p>Dành cho cần thủ muốn độ chính xác cao, khả năng ra mồi nhanh và kiểm tra dây tốt bằng ngón cái. Tuy nhiên cần thời gian tập luyện để làm chủ lực hãm gia tốc của ống dây...</p>', 'data:image/jpeg;base64,', '2026-06-03 08:04:18');
INSERT INTO `blogs` (`id`, `title`, `summary`, `content`, `image`, `created_at`) VALUES
(4, 'Hướng dẫn bảo dưỡng máy câu Shimano và Daiwa sau khi câu nước mặn', 'Quy trình 5 bước vệ sinh xả mặn, tra dầu mỡ bò chuẩn hãng để bảo vệ vòng bi Magsealed và hệ thống bánh răng mượt mà.', '<p>Nước biển là kẻ thù số một của các dòng máy câu High-End. Cho dù máy của bạn có trang bị công nghệ chống nước đỉnh cao như X-Protect của Shimano hay Magsealed của Daiwa, việc bảo dưỡng sau mỗi chuyến đi là bắt buộc.</p><h5>Bước 1: Xả bớt phanh (Drag) và xịt nước ngọt nhẹ</h5><p>Hãy siết nhẹ drag để nước không lọt vào trong các lá phanh, sau đó dùng vòi xịt nước ngọt ở chế độ phun sương để rửa trôi muối bám bên ngoài...</p>', 'data:image/jpeg;base64,', '2026-06-03 08:04:18'),
(5, 'Top 5 loại mồi giả chuyên trị Cá Chẽm và Cá Lóc bông siêu nhạy', 'Đánh giá chi tiết các dòng mồi nổi Popper, mồi chìm Minnow và mồi thìa sắt được các cần thủ KingFisher tin dùng.', '<p>Đi câu mà không hiểu tập tính săn mồi của loài cá mục tiêu thì rất dễ \"móm\". Dưới đây là danh sách 5 con mồi huyền thoại luôn nằm trong hộp đồ của các pro-angler:</p><h5>1. Mồi Popper (Mồi nổi tạo tiếng động)</h5><p>Thích hợp câu vào sáng sớm hoặc chiều tà khi cá săn mồi trên mặt nước. Tiếng \"bộp bộp\" giả lập âm thanh cá con hoảng loạn kích thích tập tính bảo vệ lãnh thổ của cá săn mồi...</p>', 'data:image/jpeg;base64,', '2026-06-03 08:04:18');

